use super::*;

/// Every `YYYY-MM` touched by the window, inclusive at both ends.
pub fn months_between(from: &str, to: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = from[..7.min(from.len())].to_string();
    let last = to[..7.min(to.len())].to_string();
    while cur <= last && out.len() < 600 {
        out.push(cur.clone());
        cur = add_calendar_months(&format!("{cur}-01"), 1)[..7].to_string();
    }
    out
}
